mapper.select:
SELECT PMST, PMKY, PMCO, PMNM, PMV1, PMV2, PMV3, PMV4, PMV5,INSERTTIMESTAMP, UPDATETIMESTAMP ,
	 (SELECT COUNT(1) FROM PARAMETER T1 WHERE PMST ='SYSTEM' AND PMKY ='DS_CITYCODE' AND T1.PMV1 = T2.PMCO)LEAFNUM
 FROM PARAMETER T2
WHERE  PMCO NOT LIKE '%****%'

	AND PMST =#{dto.pmst}


	AND PMKY =#{dto.pmky}


	AND PMCO =#{dto.pmco}


	AND pmv1 =#{dto.pmv1}


	AND pmv2 =#{dto.pmv2}

SELECT PMST, PMKY, PMCO, PMNM, PMV1, PMV2, PMV3
FROM PARAMETER
WHERE  
	PMST =#{dto.pmst}
AND PMKY =#{dto.pmky}
AND PMCO =#{dto.pmco}

mapper.update:
UPDATE PARAMETER
   SET PMNM = PMNM -1
 WHERE PMST =#{dto.pmst}
 AND PMKY =#{dto.pmky}
 AND PMCO =#{dto.pmco}
 AND to_number(PMNM) >0
